"""Multiply two matrices."""
def multiply(m1: list[list[int]], m2: list[list[int]]) -> tuple[tuple[int, ...], ...] {
    m1_rows = len(m1);
    m1_cols = len(m1[0]);
    m2_cols = len(m2[0]);
    assert m1_cols == len(m2), "Matrix multiplication not defined. Invalid dimensions.";
    new_rows = [];
    for i in range(m1_rows) {
        new_row = [];
        for j in range(m2_cols) {
            sum = 0;
            for k in range(m1_cols) {
                sum += m1[i][k] * m2[k][j];
            }
            new_row.append(sum);
        }
        new_rows.append(tuple(new_row));
    }
    return tuple(new_rows);
}

def multiply(m1: list[list[int]], m2: list[list[int]]) -> tuple[tuple[int, ...], ...] {
    m1r = len(m1);
    m1c = len(m1[0]);
    m2r = len(m2);
    m2c = len(m2[0]);
    rr = m1r;
    rc = m2c;
    assert m1c == m2r, "Matrix multiplication not defined. Invalid dimensions.";
    newRows = [];
    for i in range(0, rr) {
        newRow = [];
        for k in range(0, rc) {
            val = 0;
            for j in range(0, m1c) {
                val = val + (m1[i][j] * m2[j][k]);
            }
            newRow.append(val);
        }
        newRows.append(tuple(newRow));
    }
    return tuple(newRows);
}

