"""Return the combination of two confusion matrices."""
def matrix_combine(
    matrix_1: dict[str, dict[str, int]],
    matrix_2: dict[str, dict[str, int]]
) -> dict[str, dict[str, int]] {
    result_matrix = {};
    classes_1 = matrix_1.keys();
    classes_2 = matrix_2.keys();
    classes = set(classes_1).union(set(classes_2));
    for class_1 in classes {
        result_matrix[class_1] = {};
        for class_2 in classes {
            if class_1 in matrix_1 and class_2 in matrix_1 {
                result_matrix[class_1][class_2] = matrix_1[class_1][class_2];
            } elif class_1 in matrix_2 and class_2 in matrix_2 {
                result_matrix[class_1][class_2] = matrix_2[class_1][class_2];
            } else {
                result_matrix[class_1][class_2] = 0;
            }
        }
    }
    return result_matrix;
}

def matrix_combine(matrix_1: dict[str, dict[str, int]], matrix_2: dict[str, dict[str, int]]) -> dict[str, dict[str, int]] {
    result_matrix: dict[str, dict[str, int]] = {};
    classes_1 = list(matrix_1.keys());
    classes_2 = list(matrix_2.keys());
    classes = sorted(set(classes_1) | set(classes_2));
    for class_1 in classes {
        temp_dict: dict[str, int] = {};
        for class_2 in classes {
            tmp = 0;
            if class_1 in classes_1 and class_2 in classes_1 {
                tmp += matrix_1[class_1][class_2];
            }
            if class_1 in classes_2 and class_2 in classes_2 {
                tmp += matrix_2[class_1][class_2];
            }
            temp_dict[class_2] = tmp;
        }
        result_matrix[class_1] = temp_dict;
    }
    return result_matrix;
}

