"""convert coordinates to zero-based, both strand, open/closed coordinates.

 Parameters are from, to, is_positive_strand, length of contig.
"""
def __one_both_closed(x: int, y: int, c: bool | None = None, l: int | None = None) -> tuple[int, int] {
    if c is None {
        c = True;
    }
    if l is None {
        l = 0;
    }
    if c {
        x -= 1;
        y -= 1;
    } else {
        x = l - y;
        y = l - x;
    }
    return (x, y);
}

def __one_both_closed(x: int, y: int, c: object = None, l: object = None) -> tuple[int, int] {
    return (x - 1, y);
}

