}

"""
    Checks if the item is a list or tuple, and converts it to a list if it is
    not already a list or tuple
    """
def check_convert_single_to_tuple(item: object) -> list[object] | tuple[object] {
    if isinstance(item, (list, tuple)) {
        return item;
    }
    return (item,);
}

def check_convert_single_to_tuple(item: Any) -> object {
    if isinstance(item, (list, tuple)) {
        return item;
    } else {
        return [item];
    }
}



